import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read trial_id
    const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = trialIdRaw.trim();
    console.log(`Trial ID: ${trialId}`);

    const normalize = (name: string) => name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");

    // 2. Build editor workspace name
    const workspaceName = normalize(`harbor-ro-${trialId}`);
    console.log(`Workspace Name: ${workspaceName}`);

    // 3. Create workspace
    const { data: workspaceData, error: workspaceError } = await createWorkspace(workspaceName, {
      ttl: { days: 1 },
      enableSnapshots: true,
      credentials: { role: "Editor" },
    });

    if (workspaceError) {
      console.error("Error creating workspace:", workspaceError);
      process.exit(1);
    }

    if (!workspaceData?.credentials) {
      console.error("Workspace credentials missing");
      process.exit(1);
    }

    const editorCreds = workspaceData.credentials;
    const workspaceBucket = workspaceData.bucket;

    // 4. Put object using editor credentials
    console.log(`Writing notes/welcome.txt to ${workspaceBucket}...`);
    const { error: putError } = await put("notes/welcome.txt", "hello readonly", {
      config: {
        bucket: workspaceBucket,
        accessKeyId: editorCreds.accessKeyId,
        secretAccessKey: editorCreds.secretAccessKey,
      },
    });

    if (putError) {
      console.error("Error writing with editor credentials:", putError);
      process.exit(1);
    }

    // 5. Create ReadOnly fork
    const forkPrefix = normalize(`harbor-ro-${trialId}-readonly`);
    console.log(`Creating fork with prefix: ${forkPrefix}...`);
    const { data: forkSet, error: forkError } = await createForks(workspaceBucket, 1, {
      prefix: forkPrefix,
      credentials: { role: "ReadOnly" },
    });

    if (forkError) {
      console.error("Error creating fork:", forkError);
      process.exit(1);
    }

    if (!forkSet?.forks?.[0]?.credentials) {
      console.error("Fork or fork credentials missing");
      process.exit(1);
    }

    const readonlyCreds = forkSet.forks[0].credentials;
    const forkBucket = forkSet.forks[0].bucket;
    console.log(`Fork bucket: ${forkBucket}`);

    // 6. Attempt forbidden write
    console.log(`Attempting forbidden write to ${forkBucket}...`);
    const { error: forbiddenError } = await put("notes/forbidden.txt", "should be rejected", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      },
    });

    if (!forbiddenError) {
      console.error("Error: Forbidden write unexpectedly succeeded");
      process.exit(1);
    }

    console.log("Forbidden write rejected as expected.");
    const denial = `${forbiddenError.name ?? "Error"}: ${forbiddenError.message ?? JSON.stringify(forbiddenError)}`;
    await writeFile("/home/user/tigris-task/write-denial.log", denial, "utf-8");

    // 7. Successful read
    console.log(`Reading notes/welcome.txt from ${forkBucket}...`);
    const { data: readData, error: readError } = await get("notes/welcome.txt", "string", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      },
    });

    if (readError) {
      console.error("Error reading with readonly credentials:", readError);
      process.exit(1);
    }

    if (readData !== "hello readonly") {
      console.error(`Read back unexpected content: ${readData}`);
      process.exit(1);
    }

    await writeFile("/home/user/tigris-task/readback.txt", readData, "utf-8");
    console.log("Read back successful.");

    process.exit(0);
  } catch (err) {
    console.error("Unexpected error:", err);
    process.exit(1);
  }
}

main();
